const renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.95;renderer.localClippingEnabled=true;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.shadowMap.autoUpdate=false;host.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xffffff,0x8d9a80,1.9));const sun=new THREE.DirectionalLight(0xfff3da,2.1);sun.position.set(-32,22,9);sun.target.position.set(-41,2,-4.5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-13,right:13,top:13,bottom:-13,near:.5,far:65});sun.shadow.bias=-.0002;sun.shadow.normalBias=.025;scene.add(sun,sun.target);const fill=new THREE.DirectionalLight(0xd7e6f1,1);fill.position.set(25,12,-20);scene.add(fill);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.025,2000);const planCamera=new THREE.OrthographicCamera(-10,10,10,-10,.01,2000);planCamera.up.set(0,0,-1);let activeCamera=camera;
