 if(next==='orbit'){$('#room-view').value='overview';camera.fov=48;resize();orbitView();$('#hint').innerHTML='Drag to orbit <b>·</b> Scroll to zoom <b>·</b> Double-click to focus';}
 if(next==='plan'){$('#room-view').value='overview';activeCamera=planCamera;controls.object=planCamera;controls.enableRotate=false;planCamera.position.set(center.x,box.max.y+extent*2,center.z);controls.target.copy(center);planCamera.zoom=1;resize();planCamera.lookAt(center);controls.update();$('#cutaway').checked=true;$('#height').value=box.min.y+Math.min(size.y*.35,2.6);applyCutaway();$('#hint').innerHTML='Drag to pan <b>·</b> Scroll to zoom <b>·</b> Double-click a floor to walk there';}
 if(next==='walk'){$('#room-view').value='living';camera.fov=48;camera.setViewOffset(innerWidth,innerHeight,innerWidth>650?125:60,0,innerWidth,innerHeight);activeCamera=camera;controls.object=camera;camera.position.fromArray(interior.design.rooms[0].eye);camera.up.set(0,1,0);camera.lookAt(new THREE.Vector3().fromArray(interior.design.rooms[0].target));$('#cutaway').checked=false;applyCutaway();const direction=new THREE.Vector3();camera.getWorldDirection(direction);yaw=Math.atan2(-direction.x,-direction.z);pitch=Math.asin(THREE.MathUtils.clamp(direction.y,-.95,.95));camera.position.y=Math.max(camera.position.y,box.min.y+1.65);walkY=camera.position.y;$('#hint').innerHTML='W A S D move <b>·</b> Shift faster <b>·</b> Q / E down / up <b>·</b> Esc release';}
