function applyCutaway(){const enabled=$('#cutaway').checked;$('#cut-controls').hidden=!enabled;clip.constant=Number($('#height').value);$('#height-label').value=`${(clip.constant-box.min.y).toFixed(2)} m`;for(const [m]of materials){m.clippingPlanes=enabled?[clip]:[];m.clipShadows=true;m.needsUpdate=true;}renderer.shadowMap.needsUpdate=true;updateSection();}
let sectionLines,sectionTimer;
function updateSection(){
 clearTimeout(sectionTimer);if(sectionLines)sectionLines.visible=$('#cutaway').checked;
 if(!$('#cutaway').checked)return;
 sectionTimer=setTimeout(()=>{
  const y=clip.constant,points=[],a=new THREE.Vector3(),b=new THREE.Vector3(),c=new THREE.Vector3(),bbox=new THREE.Box3();
  for(const mesh of meshes){
   bbox.setFromObject(mesh);if(bbox.min.y>y||bbox.max.y<y)continue;
   const p=mesh.geometry.attributes.position,index=mesh.geometry.index,count=index?index.count:p.count;
   for(let i=0;i<count;i+=3){
    a.fromBufferAttribute(p,index?index.getX(i):i).applyMatrix4(mesh.matrixWorld);
    b.fromBufferAttribute(p,index?index.getX(i+1):i+1).applyMatrix4(mesh.matrixWorld);
    c.fromBufferAttribute(p,index?index.getX(i+2):i+2).applyMatrix4(mesh.matrixWorld);
    if((a.y>y&&b.y>y&&c.y>y)||(a.y<y&&b.y<y&&c.y<y))continue;
    const hits=[];
    for(const[u,v]of [[a,b],[b,c],[c,a]])if((u.y<=y&&v.y>y)||(v.y<=y&&u.y>y)){const t=(y-u.y)/(v.y-u.y);hits.push(u.x+(v.x-u.x)*t,y+.006,u.z+(v.z-u.z)*t);}
    if(hits.length===6)points.push(...hits);
   }
  }
  if(sectionLines){scene.remove(sectionLines);sectionLines.geometry.dispose();sectionLines.material.dispose();}
  const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(points,3));sectionLines=new THREE.LineSegments(geometry,new THREE.LineBasicMaterial({color:0x31443a,transparent:true,opacity:.85}));scene.add(sectionLines);
 },160);
}

async function load(){try{meta=await fetch('./assets/model-info.json').then(r=>r.json());const gltf=await new GLTFLoader(manager).loadAsync('./assets/villa.gltf');model=gltf.scene;interior=buildModernTropicalInterior(model);model.updateMatrixWorld(true);box=new THREE.Box3();model.traverse(o=>{if(o.isMesh&&visibleInTree(o))box.union(new THREE.Box3().setFromObject(o))});center=box.getCenter(new THREE.Vector3());size=box.getSize(new THREE.Vector3());let bestBox=box.clone(),bestVolume=0;for(const child of (model.children[0]?.children||model.children)){const candidate=new THREE.Box3().setFromObject(child),s=candidate.getSize(new THREE.Vector3()),volume=s.x*s.y*s.z;if(volume>bestVolume){bestVolume=volume;bestBox=candidate;}}for(const child of (model.children[0]?.children||model.children)){const candidate=new THREE.Box3().setFromObject(child),s=candidate.getSize(new THREE.Vector3());if(s.x*s.z>50&&candidate.intersectsBox(bestBox))bestBox.union(candidate);}center=bestBox.getCenter(new THREE.Vector3());fitSize=bestBox.getSize(new THREE.Vector3());extent=Math.max(fitSize.x,fitSize.z);heightBase=box.min.y;
 model.traverse(o=>{if(o.isMesh&&visibleInTree(o)){o.castShadow=true;o.receiveShadow=true;if(!o.geometry.attributes.normal)o.geometry.computeVertexNormals();o.frustumCulled=true;meshes.push(o);for(const m of (Array.isArray(o.material)?o.material:[o.material])){if(!materials.has(m)){materials.set(m,{map:m.map,color:m.color.clone()});if(!m.name.startsWith('MT |'))m.roughness=.85;if(m.transparent)m.depthWrite=false;}}}});scene.add(model);for(const [p,intensity]of[[[-39.45,2.38,-6.2],8],[[-40.3,2.3,-3.2],6],[[-38.6,4.3,-5],5]]){const light=new THREE.PointLight(0xffddb1,intensity,5,2);light.position.fromArray(p);scene.add(light);}renderer.shadowMap.needsUpdate=true;for(const room of interior.design.rooms){const option=document.createElement('option');option.value=room.id;option.textContent=room.name;$('#room-view').appendChild(option);}
 grid=new THREE.GridHelper(Math.ceil(extent*1.6),Math.ceil(extent*1.6),0xa4afa0,0xcbd2c5);grid.position.set(center.x,box.min.y-.035,center.z);grid.visible=false;scene.add(grid);
 $('#dimensions').textContent=`${size.x.toFixed(1)} × ${size.z.toFixed(1)} × ${size.y.toFixed(1)} m`;$('#model-detail').textContent=`${interior.design.items.length} interior elements · 10 spaces`;
 $('#height').min=box.min.y+.1;$('#height').max=box.max.y+.1;$('#height').value=box.max.y+.1;ready=true;resize();orbitView();$('#status').textContent='Modern tropical · ready';$('#progress').style.width='100%';$('#loading').style.display='none';window.villaExplorer={scene,model,camera,renderer,box,meta,get mode(){return mode},get activeCamera(){return activeCamera},changeMode,interior};goRoom('living');
 }catch(e){console.error(e);$('#load-text').textContent='Could not load the villa. Please reload the viewer.';$('#status').textContent='Load failed';}}
