function goRoom(id){if(!ready)return;if(id==='overview'){changeMode('orbit');return;}const room=interior.design.rooms.find(r=>r.id===id);if(!room)return;changeMode('walk');camera.fov=room.fov||48;camera.updateProjectionMatrix();camera.position.fromArray(room.eye);const dir=new THREE.Vector3().fromArray(room.target).sub(camera.position).normalize();yaw=Math.atan2(-dir.x,-dir.z);pitch=Math.asin(THREE.MathUtils.clamp(dir.y,-.95,.95));$('#room-view').value=id;}
$('#room-view').onchange=e=>goRoom(e.target.value);
$('#moodboard').onclick=()=>$('#design-dialog').showModal();$('#close-design').onclick=()=>$('#design-dialog').close();
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>changeMode(b.dataset.mode));$('#reset').onclick=()=>{$('#room-view').value='overview';changeMode('orbit')};$('#cutaway').onchange=()=>ready&&applyCutaway();$('#height').oninput=()=>ready&&applyCutaway();$('#grid').onchange=e=>{if(grid)grid.visible=e.target.checked};$('#textures').onchange=e=>{for(const[m,original]of materials){m.map=e.target.checked?original.map:null;m.color.copy(e.target.checked?original.color:new THREE.Color('#d9d8cd'));m.needsUpdate=true}};
$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();$('#fullscreen').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch{}};
$('#capture').onclick=()=>{renderer.render(scene,activeCamera);const a=document.createElement('a');a.download=`veil-of-light-${mode}.png`;a.href=renderer.domElement.toDataURL('image/png');a.click()};
function activateWalk(){walkActive=true;$('#walk-overlay').hidden=true;renderer.domElement.focus();$('#status').textContent='Walk mode · drag to look';try{const result=renderer.domElement.requestPointerLock?.();if(result?.catch)result.catch(()=>{});}catch{}}
$('#resume').onclick=activateWalk;
renderer.domElement.addEventListener('pointerdown',e=>{if(mode==='walk'){if(!walkActive)activateWalk();dragging=true;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)}});
