function validHit(hit){return !$('#cutaway').checked||hit.point.y<=clip.constant+.02;}
renderer.domElement.addEventListener('dblclick',e=>{if(!ready||mode==='walk')return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,activeCamera);const hit=raycaster.intersectObjects(meshes,false).find(validHit);if(!hit)return;if(mode==='plan'){const p=hit.point.clone();changeMode('walk');camera.position.copy(p).add(new THREE.Vector3(0,1.65,0));walkY=camera.position.y;yaw=0;pitch=-.04;}else controls.target.copy(hit.point);});
function canMove(from,delta){const distance=delta.length();if(distance<.00001)return true;raycaster.set(from,delta.clone().normalize());raycaster.far=distance+.22;const blocked=raycaster.intersectObjects(meshes,false).some(h=>validHit(h)&&!h.object.material.transparent);raycaster.far=Infinity;return !blocked;}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);if(ready){if(mode==='walk'){camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0);if(walkActive){const x=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0);const z=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);const step=new THREE.Vector3(x,0,z);if(step.lengthSq()){step.normalize().applyAxisAngle(new THREE.Vector3(0,1,0),yaw).multiplyScalar(dt*(keys.has('ShiftLeft')||keys.has('ShiftRight')?4:1.8));const dx=new THREE.Vector3(step.x,0,0),dz=new THREE.Vector3(0,0,step.z);if(canMove(camera.position,dx))camera.position.add(dx);if(canMove(camera.position,dz))camera.position.add(dz);}camera.position.y+=((keys.has('KeyE')?1:0)-(keys.has('KeyQ')?1:0))*dt*1.5;camera.position.y=THREE.MathUtils.clamp(camera.position.y,box.min.y+.35,box.max.y+5);}}else controls.update();}renderer.render(scene,activeCamera);}
animate();window.addEventListener('resize',resize);
